import ctypes
from ctypes import wintypes
import threading
from utils.logger import get_logger

logger = get_logger()
user32 = ctypes.windll.user32

WH_KEYBOARD_LL = 13
WH_MOUSE_LL = 14
WM_KEYDOWN = 0x0100
WM_SYSKEYDOWN = 0x0104
WM_KEYUP = 0x0101
WM_SYSKEYUP = 0x0105
WM_LBUTTONDOWN = 0x0201

# Magic tag for events generated by Layvix
LAYVIX_MAGIC_INFO = 0xABCD

# Modifiers
MODIFIERS = {
    0x10, 0x11, 0x12, 0x5B, 0x5C, # Shift, Ctrl, Alt, LWin, RWin
    0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5 # L/R variants
}

class KBDLLHOOKSTRUCT(ctypes.Structure):
    _fields_ = [
        ("vkCode", wintypes.DWORD),
        ("scanCode", wintypes.DWORD),
        ("flags", wintypes.DWORD),
        ("time", wintypes.DWORD),
        ("dwExtraInfo", ctypes.c_size_t)
    ]

class MSLLHOOKSTRUCT(ctypes.Structure):
    _fields_ = [
        ("pt", wintypes.POINT),
        ("mouseData", wintypes.DWORD),
        ("flags", wintypes.DWORD),
        ("time", wintypes.DWORD),
        ("dwExtraInfo", ctypes.c_size_t)
    ]

HOOKPROC = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_int, wintypes.WPARAM, ctypes.POINTER(KBDLLHOOKSTRUCT))
MOUSEHOOKPROC = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_int, wintypes.WPARAM, ctypes.POINTER(MSLLHOOKSTRUCT))

# Fix 64-bit pointer truncation for hook handles
user32.SetWindowsHookExA.restype = wintypes.HHOOK
user32.UnhookWindowsHookEx.restype = wintypes.BOOL
user32.UnhookWindowsHookEx.argtypes = [wintypes.HHOOK]
user32.CallNextHookEx.restype = ctypes.c_long

class KeyboardHookManager:
    def __init__(self):
        self.kbd_hook_id = None
        self.mouse_hook_id = None
        self.is_running = False
        self.is_sleeping = False
        
        self.on_key_down = None # Callback: fn(vk_code, scan_code, char_str) -> bool (True to suppress)
        self.on_mouse_click = None # Callback: fn() -> None
        
        self.kbd_hook_proc = HOOKPROC(self._kbd_hook_proc)
        self.mouse_hook_proc = MOUSEHOOKPROC(self._mouse_hook_proc)
        self.thread_id = None
        self._hook_thread = None

    def set_sleeping(self, sleeping: bool):
        self.is_sleeping = sleeping

    def start(self):
        self.is_running = True
        if self.kbd_hook_id is not None or self.mouse_hook_id is not None:
            logger.warning("[HOOK] Attempted to start hook while another is active! Stopping old hook first.")
            self.stop()
            self.is_running = True
            
        def _run_hook():
            self.thread_id = ctypes.windll.kernel32.GetCurrentThreadId()
            
            self.kbd_hook_id = user32.SetWindowsHookExA(WH_KEYBOARD_LL, self.kbd_hook_proc, 0, 0)
            if not self.kbd_hook_id:
                logger.error("[HOOK] Failed to install WH_KEYBOARD_LL")
                
            self.mouse_hook_id = user32.SetWindowsHookExA(WH_MOUSE_LL, self.mouse_hook_proc, 0, 0)
            if not self.mouse_hook_id:
                logger.error("[HOOK] Failed to install WH_MOUSE_LL")
            
            logger.info("[HOOK] Low-Level Keyboard & Mouse Hooks started")
            msg = wintypes.MSG()
            while user32.GetMessageA(ctypes.byref(msg), 0, 0, 0) > 0:
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageA(ctypes.byref(msg))
                
        self._hook_thread = threading.Thread(target=_run_hook, daemon=True, name="KbdHookThread")
        self._hook_thread.start()

    def stop(self):
        self.is_running = False
        if self.kbd_hook_id:
            user32.UnhookWindowsHookEx(self.kbd_hook_id)
            self.kbd_hook_id = None
        if self.mouse_hook_id:
            user32.UnhookWindowsHookEx(self.mouse_hook_id)
            self.mouse_hook_id = None
        if self.thread_id:
            user32.PostThreadMessageA(self.thread_id, 0x0012, 0, 0) # WM_QUIT

    def _get_char_from_keys(self, vk, scan_code):
        """Translates virtual key to unicode char based on foreground thread state."""
        state = (ctypes.c_byte * 256)()
        user32.GetKeyboardState(state)
        
        hwnd = user32.GetForegroundWindow()
        thread_id = user32.GetWindowThreadProcessId(hwnd, 0)
        hkl = user32.GetKeyboardLayout(thread_id)
        
        buff = ctypes.create_unicode_buffer(4)
        # wFlags=4 prevents ToUnicodeEx from modifying the keyboard state 
        # and generating duplicate WM_CHAR messages in the target window.
        result = user32.ToUnicodeEx(vk, scan_code, state, buff, 4, 4, hkl)
        
        if result > 0:
            return buff.value[:result]
        return ""

    def _kbd_hook_proc(self, nCode, wParam, lParam):
        if nCode < 0:
            return user32.CallNextHookEx(self.kbd_hook_id, nCode, wParam, lParam)

        kb = lParam.contents
        
        # Recursion Prevention: Ignore our own injected events
        if kb.dwExtraInfo == LAYVIX_MAGIC_INFO:
            return user32.CallNextHookEx(self.kbd_hook_id, nCode, wParam, lParam)

        vk = kb.vkCode
        
        # Modifier Filtering: Pass through immediately
        if vk in MODIFIERS:
            return user32.CallNextHookEx(self.kbd_hook_id, nCode, wParam, lParam)

        if wParam == WM_KEYDOWN or wParam == WM_SYSKEYDOWN:
            if self.on_key_down:
                char_str = self._get_char_from_keys(vk, kb.scanCode)
                suppress = self.on_key_down(vk, kb.scanCode, char_str)
                if suppress:
                    return 1 # Block key from reaching OS

        return user32.CallNextHookEx(self.kbd_hook_id, nCode, wParam, lParam)

    def _mouse_hook_proc(self, nCode, wParam, lParam):
        if nCode < 0:
            return user32.CallNextHookEx(self.mouse_hook_id, nCode, wParam, lParam)

        if wParam == WM_LBUTTONDOWN:
            if self.on_mouse_click:
                ms = lParam.contents
                suppress = self.on_mouse_click(ms.pt.x, ms.pt.y)
                if suppress:
                    return 1

        return user32.CallNextHookEx(self.mouse_hook_id, nCode, wParam, lParam)
